<script setup>
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'

const props = defineProps({ slug: { type: String, required: true }, teamSlug: { type: String, default: '' } })
const data = ref(null)
const loading = ref(true)
const error = ref('')

const club = computed(() => data.value?.club ?? {})
const isTeam = computed(() => Boolean(props.teamSlug))
const teamsById = computed(() => Object.fromEntries((data.value?.teams ?? []).map(team => [team.id, team])))
const announcements = computed(() => (data.value?.posts ?? []).filter(post => post.kind === 'announcement'))
const news = computed(() => (data.value?.posts ?? []).filter(post => post.kind !== 'announcement'))
const upcoming = computed(() => (data.value?.matches ?? []).filter(match => match.status === 'scheduled').sort((a,b) => a.scheduledAt.localeCompare(b.scheduledAt)).slice(0, 6))
const results = computed(() => (data.value?.matches ?? []).filter(match => match.status === 'completed').slice(0, 8))
const activePanel = ref('')
const activeTeamData = ref(null)
const activeTeamSection = ref('overview')
const teamModalLoading = ref(false)
const teamModalError = ref('')
const teamModalCache = new Map()
let teamRequestSequence = 0
const homeTeams = computed(() => (data.value?.teams ?? []).slice(0, 4))
const featuredMatch = computed(() => {
  const matches = data.value?.matches ?? []
  return matches.find(match => match.status === 'live') || upcoming.value[0] || results.value[0] || null
})
const homeTiles = computed(() => [
  ...homeTeams.value.map((team, index) => ({
    id: `team-${team.id}`, kind: 'team', team,
    label: team.name, sub: team.championship || team.category || 'Scopri la squadra',
    icon: ['🏐', '⚡', '🏆', '⭐'][index % 4],
  })),
  { id: 'matches', kind: 'panel', panel: 'matches', label: 'Partite', sub: `${data.value?.matches?.length ?? 0} appuntamenti`, icon: '📅' },
  { id: 'announcements', kind: 'panel', panel: 'announcements', label: 'Annunci', sub: `${announcements.value.length} comunicazioni`, icon: '📣' },
  { id: 'news', kind: 'panel', panel: 'news', label: 'News', sub: `${news.value.length} dal club`, icon: '📰' },
  { id: 'gallery', kind: 'panel', panel: 'gallery', label: 'Gallery', sub: `${data.value?.gallery?.length ?? 0} fotografie`, icon: '📸' },
])

const theme = computed(() => ({
  '--club-primary': club.value.primaryColor || '#172554',
  '--club-accent': club.value.secondaryColor || '#f59e0b',
}))

async function load() {
  loading.value = true
  error.value = ''
  try {
    const endpoint = props.teamSlug
      ? `/api/v1/clubs/${encodeURIComponent(props.slug)}/teams/${encodeURIComponent(props.teamSlug)}`
      : `/api/v1/clubs/${encodeURIComponent(props.slug)}/home`
    const response = await fetch(endpoint)
    if (!response.ok) throw new Error(response.status)
    data.value = await response.json()
  } catch { error.value = 'Questa pagina non è ancora disponibile.' }
  finally { loading.value = false }
}

function formatDate(value) {
  if (!value) return 'Data da definire'
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return value
  return new Intl.DateTimeFormat('it-IT', { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }).format(date)
}
function initials(name) { return String(name || '').split(/\s+/).map(part => part[0]).join('').slice(0,2).toUpperCase() }
function teamName(match) { return data.value?.team?.name || teamsById.value[match.teamId]?.name || 'Squadra' }
function scoreLabel(match) { return match.home ? `${match.scoreFor} – ${match.scoreAgainst}` : `${match.scoreAgainst} – ${match.scoreFor}` }
function openPanel(panel) {
  activeTeamData.value = null
  activePanel.value = panel
}
async function openTeam(team) {
  const requestId = ++teamRequestSequence
  activePanel.value = 'team'
  activeTeamSection.value = 'overview'
  activeTeamData.value = null
  teamModalError.value = ''
  teamModalLoading.value = true
  if (teamModalCache.has(team.slug)) {
    activeTeamData.value = teamModalCache.get(team.slug)
    teamModalLoading.value = false
    return
  }
  try {
    const response = await fetch(`/api/v1/clubs/${encodeURIComponent(props.slug)}/teams/${encodeURIComponent(team.slug)}`)
    if (!response.ok) throw new Error(response.status)
    const payload = await response.json()
    if (requestId !== teamRequestSequence) return
    teamModalCache.set(team.slug, payload)
    activeTeamData.value = payload
  } catch {
    if (requestId === teamRequestSequence) teamModalError.value = 'I dettagli della squadra non sono disponibili.'
  } finally {
    if (requestId === teamRequestSequence) teamModalLoading.value = false
  }
}
function closePanel() {
  teamRequestSequence += 1
  activePanel.value = ''
  activeTeamData.value = null
  teamModalLoading.value = false
  teamModalError.value = ''
}
function handleKeydown(event) { if (event.key === 'Escape' && activePanel.value) closePanel() }

watch(() => [props.slug, props.teamSlug], () => { teamModalCache.clear(); closePanel(); load() })
onMounted(() => { load(); window.addEventListener('keydown', handleKeydown) })
onBeforeUnmount(() => window.removeEventListener('keydown', handleKeydown))
</script>

<template>
  <main class="club-page" :style="theme">
    <div v-if="loading" class="state">Caricamento Club Hub…</div>
    <div v-else-if="error" class="state error"><strong>Pagina non disponibile</strong><span>{{ error }}</span></div>
    <template v-else>
      <header v-if="isTeam" class="topbar">
        <a class="brand" :href="`/club/${slug}`">
          <img v-if="club.logoUrl" :src="club.logoUrl" :alt="club.name" />
          <span v-else class="logo-fallback">{{ initials(club.name) }}</span>
          <span><strong>{{ club.name }}</strong><small>{{ club.seasonLabel }}</small></span>
        </a>
        <nav><a :href="`/club/${slug}`">Home</a><a :href="`/club/${slug}#squadre`">Squadre</a><a :href="`/club/${slug}#notizie`">Notizie</a><a :href="`/club/${slug}#gallery`">Gallery</a></nav>
      </header>

      <template v-if="!isTeam">
        <section class="cd-stage">
          <div class="cd-shell">
            <header class="cd-hero" :style="club.heroImageUrl ? { backgroundImage: `linear-gradient(135deg, color-mix(in srgb, var(--club-primary) 92%, transparent), rgba(3,7,18,.45)), url('${club.heroImageUrl}')` } : {}">
              <div class="cd-orb cd-orb-one"></div><div class="cd-orb cd-orb-two"></div>
              <div class="cd-hero-top"><span class="cd-status"><i></i> PORTALE UFFICIALE</span><span class="cd-season">{{ club.seasonLabel }}</span></div>
              <div class="cd-identity">
                <div class="cd-logo"><img v-if="club.logoUrl" :src="club.logoUrl" :alt="club.name" /><span v-else>{{ initials(club.name) }}</span></div>
                <div><p>{{ club.city || 'VOLLEY CLUB' }}</p><h1>{{ club.name }}</h1><small>{{ club.tagline || 'Una società, tutte le squadre, una sola passione.' }}</small></div>
              </div>
              <button v-if="announcements[0]" class="cd-breaking" type="button" @click="openPanel('announcements')"><b>{{ announcements[0].pinned ? 'IN EVIDENZA' : 'ANNUNCIO' }}</b><span>{{ announcements[0].title }}</span><i>›</i></button>
            </header>

            <div class="cd-body">
              <button v-if="featuredMatch" class="cd-match" type="button" @click="openPanel('matches')">
                <div class="cd-match-head"><span :class="{ live: featuredMatch.status === 'live' }">{{ featuredMatch.status === 'live' ? '● LIVE ORA' : featuredMatch.status === 'completed' ? 'ULTIMO RISULTATO' : '⚡ PROSSIMA PARTITA' }}</span><time>{{ formatDate(featuredMatch.scheduledAt) }}</time></div>
                <div class="cd-versus"><strong>{{ featuredMatch.home ? teamName(featuredMatch) : featuredMatch.opponent }}</strong><b>{{ featuredMatch.status === 'completed' ? scoreLabel(featuredMatch) : 'VS' }}</b><strong>{{ featuredMatch.home ? featuredMatch.opponent : teamName(featuredMatch) }}</strong></div>
                <small>{{ teamName(featuredMatch) }} · {{ featuredMatch.location || featuredMatch.competition || 'Dettagli partita' }}</small>
              </button>
              <button v-else class="cd-match cd-match-empty" type="button" @click="openPanel('matches')"><span>📅</span><div><strong>Calendario in arrivo</strong><small>Apri la sezione partite</small></div><i>›</i></button>

              <div class="cd-grid">
                <template v-for="(tile, index) in homeTiles" :key="tile.id">
                  <button v-if="tile.kind === 'team'" :class="['cd-tile', `tone-${index + 1}`]" type="button" :style="tile.team.heroImageUrl ? { backgroundImage: `linear-gradient(150deg, color-mix(in srgb, var(--club-primary) 75%, transparent), rgba(3,7,18,.84)), url('${tile.team.heroImageUrl}')` } : {}" @click="openTeam(tile.team)">
                    <span class="cd-icon"><img v-if="tile.team.logoUrl" :src="tile.team.logoUrl" alt="" /><i v-else>{{ tile.icon }}</i></span><strong>{{ tile.label }}</strong><small>{{ tile.sub }}</small><b>APRI <i>›</i></b>
                  </button>
                  <button v-else :class="['cd-tile', 'cd-action', `tone-${index + 1}`]" type="button" @click="openPanel(tile.panel)"><span class="cd-icon"><i>{{ tile.icon }}</i></span><strong>{{ tile.label }}</strong><small>{{ tile.sub }}</small><b>VEDI <i>›</i></b></button>
                </template>
              </div>
            </div>
          </div>
        </section>

        <transition name="cd-modal">
          <div v-if="activePanel" class="cd-modal-backdrop" @click.self="closePanel">
            <section :class="['cd-modal', { 'cd-modal-team': activePanel === 'team' }]" role="dialog" aria-modal="true">
              <header><div><p class="kicker">{{ club.name }}</p><h2>{{ activePanel === 'team' ? (activeTeamData?.team?.name || 'Squadra') : activePanel === 'matches' ? 'Partite' : activePanel === 'announcements' ? 'Annunci' : activePanel === 'news' ? 'News' : 'Photo gallery' }}</h2></div><button type="button" aria-label="Chiudi" @click="closePanel">×</button></header>
              <div v-if="activePanel === 'team'" class="cd-team-modal">
                <div v-if="teamModalLoading" class="cd-team-state"><span class="cd-spinner"></span><strong>Caricamento squadra…</strong></div>
                <div v-else-if="teamModalError" class="cd-team-state cd-team-error"><strong>{{ teamModalError }}</strong><button type="button" @click="closePanel">Chiudi</button></div>
                <template v-else-if="activeTeamData">
                  <div class="cd-team-intro" :style="activeTeamData.team.heroImageUrl ? { backgroundImage: `linear-gradient(110deg, color-mix(in srgb, var(--club-primary) 93%, transparent), rgba(3,7,18,.5)), url('${activeTeamData.team.heroImageUrl}')` } : {}">
                    <div class="cd-team-logo"><img v-if="activeTeamData.team.logoUrl" :src="activeTeamData.team.logoUrl" alt="" /><span v-else>{{ initials(activeTeamData.team.name) }}</span></div>
                    <div><b>{{ activeTeamData.team.category }}</b><strong>{{ activeTeamData.team.championship || activeTeamData.team.name }}</strong><small>{{ activeTeamData.team.description || 'Calendario, risultati, roster e contenuti della squadra.' }}</small></div>
                  </div>
                  <nav class="cd-team-tabs" aria-label="Sezioni squadra">
                    <button v-for="section in [{ id: 'overview', label: 'Panoramica' }, { id: 'matches', label: 'Partite' }, { id: 'roster', label: 'Roster' }, { id: 'news', label: 'News' }, { id: 'gallery', label: 'Gallery' }]" :key="section.id" type="button" :class="{ active: activeTeamSection === section.id }" @click="activeTeamSection = section.id">{{ section.label }}</button>
                  </nav>
                  <div class="cd-team-content">
                    <section v-if="activeTeamSection === 'overview'" class="cd-team-overview">
                      <div class="cd-team-stats"><button type="button" @click="activeTeamSection = 'matches'"><b>{{ activeTeamData.matches?.length || 0 }}</b><span>Partite</span></button><button type="button" @click="activeTeamSection = 'roster'"><b>{{ activeTeamData.players?.length || 0 }}</b><span>Atleti</span></button><button type="button" @click="activeTeamSection = 'news'"><b>{{ activeTeamData.posts?.length || 0 }}</b><span>Notizie</span></button><button type="button" @click="activeTeamSection = 'gallery'"><b>{{ activeTeamData.gallery?.length || 0 }}</b><span>Foto</span></button></div>
                      <div class="cd-team-next" v-if="activeTeamData.matches?.[0]"><span>PROSSIMO APPUNTAMENTO</span><strong>{{ activeTeamData.matches[0].home ? activeTeamData.team.name : activeTeamData.matches[0].opponent }} <i>{{ activeTeamData.matches[0].status === 'completed' ? scoreLabel(activeTeamData.matches[0]) : 'VS' }}</i> {{ activeTeamData.matches[0].home ? activeTeamData.matches[0].opponent : activeTeamData.team.name }}</strong><small>{{ formatDate(activeTeamData.matches[0].scheduledAt) }} · {{ activeTeamData.matches[0].location || activeTeamData.matches[0].competition }}</small></div>
                      <p v-else class="cd-empty">Il prossimo appuntamento sarà pubblicato a breve.</p>
                    </section>
                    <section v-else-if="activeTeamSection === 'matches'" class="cd-team-list"><article v-for="match in activeTeamData.matches" :key="match.id" class="cd-modal-match"><div><b>{{ match.competition || activeTeamData.team.name }}</b><time>{{ formatDate(match.scheduledAt) }}</time></div><strong>{{ match.home ? activeTeamData.team.name : match.opponent }} <i>{{ match.status === 'completed' ? scoreLabel(match) : 'VS' }}</i> {{ match.home ? match.opponent : activeTeamData.team.name }}</strong><small>{{ match.roundLabel }} · {{ match.location }}</small></article><p v-if="!activeTeamData.matches?.length" class="cd-empty">Calendario in aggiornamento.</p></section>
                    <section v-else-if="activeTeamSection === 'roster'" class="cd-team-roster"><article v-for="player in activeTeamData.players" :key="player.id"><div><img v-if="player.imageUrl" :src="player.imageUrl" :alt="`${player.firstName} ${player.lastName}`" /><span v-else>{{ player.jerseyNumber || initials(`${player.firstName} ${player.lastName}`) }}</span></div><small>{{ player.role }}</small><strong>{{ player.firstName }} {{ player.lastName }}</strong><b v-if="player.jerseyNumber">#{{ player.jerseyNumber }}</b></article><p v-if="!activeTeamData.players?.length" class="cd-empty">Roster in aggiornamento.</p></section>
                    <section v-else-if="activeTeamSection === 'news'" class="cd-team-news"><article v-for="post in activeTeamData.posts" :key="post.id"><img v-if="post.imageUrl" :src="post.imageUrl" :alt="post.title" /><div><span>{{ post.kind === 'announcement' ? 'ANNUNCIO' : 'NEWS' }}</span><h3>{{ post.title }}</h3><p>{{ post.excerpt || post.body }}</p></div></article><p v-if="!activeTeamData.posts?.length" class="cd-empty">Nessuna notizia pubblicata.</p></section>
                    <section v-else class="cd-team-gallery"><figure v-for="photo in activeTeamData.gallery" :key="photo.id"><img :src="photo.imageUrl" :alt="photo.title || photo.caption" /><figcaption>{{ photo.title || photo.caption }}</figcaption></figure><p v-if="!activeTeamData.gallery?.length" class="cd-empty">La gallery è ancora vuota.</p></section>
                  </div>
                </template>
              </div>
              <div v-else-if="activePanel === 'matches'" class="cd-modal-list"><article v-for="match in data.matches" :key="match.id" class="cd-modal-match"><div><b>{{ teamName(match) }}</b><time>{{ formatDate(match.scheduledAt) }}</time></div><strong>{{ match.home ? teamName(match) : match.opponent }} <i>{{ match.status === 'completed' ? scoreLabel(match) : 'VS' }}</i> {{ match.home ? match.opponent : teamName(match) }}</strong><small>{{ match.competition }} · {{ match.location }}</small></article><p v-if="!data.matches?.length" class="cd-empty">Calendario in aggiornamento.</p></div>
              <div v-else-if="activePanel === 'announcements'" class="cd-modal-list"><article v-for="post in announcements" :key="post.id" class="cd-modal-post"><span>{{ post.pinned ? 'IN EVIDENZA' : post.teamName || 'SOCIETÀ' }}</span><h3>{{ post.title }}</h3><p>{{ post.body || post.excerpt }}</p><time>{{ formatDate(post.publishedAt) }}</time></article><p v-if="!announcements.length" class="cd-empty">Nessun annuncio pubblicato.</p></div>
              <div v-else-if="activePanel === 'news'" class="cd-modal-news"><article v-for="post in news" :key="post.id"><img v-if="post.imageUrl" :src="post.imageUrl" :alt="post.title" /><div><span>{{ post.teamName || 'SOCIETÀ' }}</span><h3>{{ post.title }}</h3><p>{{ post.excerpt || post.body }}</p></div></article><p v-if="!news.length" class="cd-empty">Nessuna notizia pubblicata.</p></div>
              <div v-else class="cd-modal-gallery"><figure v-for="photo in data.gallery" :key="photo.id"><img :src="photo.imageUrl" :alt="photo.title || photo.caption" /><figcaption>{{ photo.title || photo.teamName }}</figcaption></figure><p v-if="!data.gallery?.length" class="cd-empty">La gallery è ancora vuota.</p></div>
            </section>
          </div>
        </transition>
      </template>

      <template v-else>
        <section class="team-hero" :style="data.team.heroImageUrl ? { backgroundImage: `linear-gradient(110deg, rgba(4,10,24,.95), rgba(4,10,24,.3)), url('${data.team.heroImageUrl}')` } : {}">
          <div class="shell"><a class="back" :href="`/club/${slug}`">← Tutte le squadre</a><div class="team-title"><div class="team-badge large"><img v-if="data.team.logoUrl" :src="data.team.logoUrl" alt="" /><span v-else>{{ initials(data.team.name) }}</span></div><div><p class="kicker">{{ data.team.category }}</p><h1>{{ data.team.name }}</h1><p>{{ data.team.championship }}</p></div></div></div>
        </section>
        <div class="team-content shell">
          <section class="section compact"><div class="section-heading"><div><p class="kicker">STAGIONE</p><h2>Calendario e risultati</h2></div></div><div class="fixture-list"><article v-for="match in data.matches" :key="match.id" class="fixture"><div><time>{{ formatDate(match.scheduledAt) }}</time><small>{{ match.competition }} · {{ match.roundLabel }}</small></div><div class="fixture-teams"><strong>{{ match.home ? data.team.name : match.opponent }}</strong><b :class="{ completed: match.status === 'completed' }">{{ match.status === 'completed' ? scoreLabel(match) : 'VS' }}</b><strong>{{ match.home ? match.opponent : data.team.name }}</strong></div><span :class="['status', match.status]">{{ match.status === 'completed' ? 'Conclusa' : match.status === 'live' ? 'Live' : 'Programmata' }}</span></article><p v-if="!data.matches?.length" class="empty">Il calendario sarà pubblicato a breve.</p></div></section>
          <section class="section compact"><div class="section-heading"><div><p class="kicker">LA SQUADRA</p><h2>Roster</h2></div></div><div class="roster-grid"><article v-for="player in data.players" :key="player.id" class="player"><div class="player-photo"><img v-if="player.imageUrl" :src="player.imageUrl" :alt="`${player.firstName} ${player.lastName}`" /><span v-else>{{ player.jerseyNumber || initials(`${player.firstName} ${player.lastName}`) }}</span></div><div><small>{{ player.role }}</small><h3>{{ player.firstName }} {{ player.lastName }}</h3><b v-if="player.jerseyNumber">#{{ player.jerseyNumber }}</b></div></article><p v-if="!data.players?.length" class="empty">Roster in aggiornamento.</p></div></section>
          <section v-if="data.posts?.length" class="section compact"><div class="section-heading"><div><p class="kicker">NOTIZIE</p><h2>Dalla squadra</h2></div></div><div class="news-grid"><article v-for="post in data.posts.slice(0,6)" :key="post.id" class="news-card"><div v-if="post.imageUrl" class="news-image" :style="{ backgroundImage: `url('${post.imageUrl}')` }"></div><div class="news-body"><h3>{{ post.title }}</h3><p>{{ post.excerpt || post.body }}</p></div></article></div></section>
          <section v-if="data.gallery?.length" class="section compact"><div class="section-heading"><div><p class="kicker">GALLERY</p><h2>Momenti della squadra</h2></div></div><div class="gallery-grid team-gallery"><figure v-for="photo in data.gallery" :key="photo.id"><img :src="photo.imageUrl" :alt="photo.title" loading="lazy" /></figure></div></section>
        </div>
      </template>

      <footer v-if="isTeam"><div class="brand"><img v-if="club.logoUrl" :src="club.logoUrl" alt="" /><span><strong>{{ club.name }}</strong><small>{{ club.city }}</small></span></div><p>Club Hub powered by ArenaBoostX</p></footer>
    </template>
  </main>
</template>

